/**
 * A Tier 0 "schema vertical": a named set of zero-shot labels handed to the NER
 * backend *in addition to* the base categories (`Person`, `Organization`, `Location`,
 * `Email`, `Phone`). No weights are loaded and no model is reloaded — a vertical is
 * arguments to an inference call, nothing more. See
 * `superpowers/specs/2026-07-31-vertical-model-specialisation-design.md` §4.1.
 *
 * # Footgun: the alias-table collision
 *
 * `to_pii_category` maps some `Custom` label strings onto existing
 * `PiiCategory` variants *before* they would otherwise become
 * `PiiCategory.Custom(label)` — for example the label `"iban"` (case-insensitively)
 * becomes `Iban`, not `Custom("iban")`. A vertical author
 * who picks a label that happens to collide with that alias table gets the aliased
 * category's downstream behaviour (its pseudonym token name, its place in exports,
 * its interaction with other detectors) instead of a bespoke `Custom` category. This
 * is deliberate for the *known* aliases (a vertical calling something `"iban"` should
 * get real IBAN handling) but is easy to trip over by accident with a near-miss label
 * (`"iban_number"` does *not* alias and stays `Custom("iban_number")`). Check
 * `to_pii_category`'s alias table before choosing a label if the distinction matters
 * to you.
 */
export interface VerticalConfig {
  /** Stable identifier recorded in the audit chain. */
  readonly id?: string;
  /** Zero-shot labels handed to the NER backend in addition to the base categories. */
  readonly labels?: Array<string>;
}

/**
 * Policy controlling when VLM (Vision Language Model) OCR is used as a fallback.
 *
 * This knob is syntactic sugar over the explicit `OcrPipelineConfig` stage
 * ordering. When `vlm_fallback` is set and `pipeline` is `None`, an equivalent
 * pipeline is synthesised at extraction time:
 *
 * - `VlmFallbackPolicy.Disabled` — no synthesis; single-backend mode (default).
 * - `VlmFallbackPolicy.OnLowQuality` — tries the classical backend first; if the
 *   result scores below `quality_threshold`, tries VLM.
 * - `VlmFallbackPolicy.Always` — skips the classical backend and sends every page
 *   to the VLM.
 *
 * When `OcrConfig.pipeline` is explicitly set, `vlm_fallback` is ignored — the
 * explicit pipeline takes precedence.
 * @throws Both `OnLowQuality` and `Always` require `OcrConfig.vlm_config` to be `Some`.
 * Constructing an `OcrConfig` with one of these policies but no `vlm_config` is
 * detected by `OcrConfig.validate` and will surface as a
 * `Validation` error at extraction time, not a panic.
 */
export type VlmFallbackPolicy =
  | { mode: "disabled" }
  | { mode: "on_low_quality"; qualityThreshold: number }
  | { mode: "always" };

